insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000700081', '40000000-0000-4000-8000-000000070008', 'Identifique a informação', 'A raiz quadrada é a única parte que pode restringir x.', 1), ('70000000-0000-4000-8000-000000700082', '40000000-0000-4000-8000-000000070008', 'Escreva a condição', '$9-x\ge0$.', 2), ('70000000-0000-4000-8000-000000700083', '40000000-0000-4000-8000-000000070008', 'Faça o cálculo', '$x\le9$.', 3), ('70000000-0000-4000-8000-000000700084', '40000000-0000-4000-8000-000000070008', 'Interprete o resultado', 'Todos os números menores ou iguais a 9 são aceitos.', 4), ('70000000-0000-4000-8000-000000700085', '40000000-0000-4000-8000-000000070008', 'Confira a restrição', '$x=9$ produz raiz de zero e precisa permanecer no domínio.', 5)
