insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000070031', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000009', 'multiple_choice', 'easy', 'published', 'Calcule $\lim_{x\to2}\frac{x^2-4}{x-2}$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000700311', '40000000-0000-4000-8000-000000070031', 'A', '$4$', 1), ('50000000-0000-4000-8000-000000700312', '40000000-0000-4000-8000-000000070031', 'B', '$2$', 2), ('50000000-0000-4000-8000-000000700313', '40000000-0000-4000-8000-000000070031', 'C', '$5$', 3), ('50000000-0000-4000-8000-000000700314', '40000000-0000-4000-8000-000000070031', 'D', 'Não existe.', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000070031', '50000000-0000-4000-8000-000000700311') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000070031', '30000000-0000-4000-8000-000000000018', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000700311', '40000000-0000-4000-8000-000000070031', 'A substituição direta produz a forma indeterminada zero sobre zero.', 1), ('60000000-0000-4000-8000-000000700312', '40000000-0000-4000-8000-000000070031', 'Fatore diferença de quadrados e simplifique antes de tomar o limite.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000070031', '$4$.', 'A forma zero sobre zero não é uma resposta: ela sinaliza que a expressão deve ser reorganizada. A diferença de quadrados revela um fator x menos a que pode ser cancelado fora do ponto problemático. Depois da simplificação, a função restante é contínua e pode ser avaliada diretamente no ponto de aproximação.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000700311', '40000000-0000-4000-8000-000000070031', 'Identifique a informação', 'Substituir 2 inicialmente gera zero sobre zero.', 1), ('70000000-0000-4000-8000-000000700312', '40000000-0000-4000-8000-000000070031', 'Escreva a condição', '$x^2-4=(x-2)(x+2)$.', 2), ('70000000-0000-4000-8000-000000700313', '40000000-0000-4000-8000-000000070031', 'Faça o cálculo', '$\frac{x^2-4}{x-2}=x+2,;x\ne2$.', 3), ('70000000-0000-4000-8000-000000700314', '40000000-0000-4000-8000-000000070031', 'Interprete o resultado', '$lim_{x\to2}(x+2)=4$.', 4), ('70000000-0000-4000-8000-000000700315', '40000000-0000-4000-8000-000000070031', 'Confira a restrição', 'O cancelamento vale perto do ponto, exatamente o que o limite exige.', 5)
